/* Rimon: no-op GameDistribution SDK stub. No network, no ads. Ad calls resolve immediately. */
(function(){
  function ev(n){try{var o=window.GD_OPTIONS;if(o&&o.onEvent)o.onEvent({name:n,message:'',status:'success'});}catch(e){}}
  window.gdsdk={
    showAd:function(){ev('SDK_GAME_PAUSE');return new Promise(function(r){setTimeout(function(){ev('SDK_GAME_START');r();},300);});},
    preloadAd:function(){return Promise.resolve();},
    cancelAd:function(){return Promise.resolve();},
    sendEvent:function(){return Promise.resolve();},
    getSession:function(){return Promise.resolve({ads:{display:{enabled:false}},location:{}});},
    openConsole:function(){},
    AdType:{Interstitial:'interstitial',Rewarded:'rewarded',Display:'display'}
  };
  setTimeout(function(){ev('SDK_READY');ev('SDK_GAME_START');},50);
})();
